<?php use App\services\Pricing;use App\Models\DB;$groups=[];$subtotal=0;foreach($items as $i){$i['current_price']=Pricing::price($i,(int)$i['quantity'],DB::all('SELECT * FROM price_tiers WHERE offer_id=? ORDER BY min_qty',[$i['offer_id']]));$groups[$i['supplier_id']][]=$i;$subtotal+=$i['current_price']*$i['quantity'];}$requestKey=bin2hex(random_bytes(32)); ?>
<div class="page-heading"><div><div class="eyebrow">MAKE ROOM FOR GOOD THINGS</div><h1>Your wholesale cart<span class="green">.</span></h1><p>One checkout. Individual orders for each supplier.</p></div><a href="/catalog" class="text-link">Continue shopping →</a></div>
<?php if(!$items):?><div class="empty-state"><span>▣</span><h2>Your bag has possibilities.</h2><p>Add your first wholesale offer to get started.</p><a href="/catalog" class="btn btn-primary">Find your next best seller</a></div><?php else:?>
<div class="checkout-grid"><div><?php foreach($groups as $supplier=>$rows):?><section class="panel cart-supplier"><div class="section-heading"><h2><?= e($rows[0]['supplier']) ?></h2><span class="badge soft-badge">Supplier order</span></div><?php foreach($rows as $i):?><div class="cart-row"><div><a class="strong-link" href="/product?id=<?= $i['product_id'] ?>"><?= e($i['name']) ?></a><small><?= e($i['pack_size'].' '.$i['unit']) ?> / pack · <?= money($i['current_price']) ?></small><small>Min <?= $i['min_qty'] ?> · increments <?= $i['increment_qty'] ?> · available <?= $i['stock'] ?></small></div><form action="/cart/update" method="post" class="inline-form"><?= csrf() ?><input type="hidden" name="offer_id" value="<?= $i['offer_id'] ?>"><input type="number" aria-label="Quantity for <?= e($i['name']) ?>" name="quantity" min="<?= $i['min_qty'] ?>" step="<?= $i['increment_qty'] ?>" max="<?= $i['stock'] ?>" value="<?= $i['quantity'] ?>" required><button class="btn btn-outline-secondary btn-sm">Update</button></form><strong><?= money($i['current_price']*$i['quantity']) ?></strong><form action="/cart/remove" method="post"><?= csrf() ?><input type="hidden" name="item_id" value="<?= $i['id'] ?>"><button class="icon-button" aria-label="Remove <?= e($i['name']) ?>">×</button></form></div><?php endforeach;?></section><?php endforeach;?></div>
<form method="post" action="/checkout/create" class="panel checkout-summary"><?= csrf() ?><input type="hidden" name="request_key" value="<?= $requestKey ?>"><h2>Let’s get it to you.</h2><label>Saved delivery address<select name="address_id"><option value="0">Pickup only / select an address</option><?php foreach($addresses as $a):?><option value="<?= $a['id'] ?>"><?= e($a['label'].' — '.$a['city']) ?></option><?php endforeach;?></select></label><a href="/profile">Add a delivery address →</a><hr><?php foreach($groups as $supplier=>$rows):$f=$rows[0];?><label><?= e($f['supplier']) ?><select name="fulfillment[<?= $supplier ?>]" required><option value="">Choose fulfillment</option><?php if($f['pickup']):?><option value="pickup">Pickup — no delivery fee</option><?php endif;?><?php if($f['delivery']&&$f['delivery_fee']!==null):?><option value="delivery">Delivery — <?= money($f['delivery_fee']) ?></option><?php endif;?></select></label><?php if($f['delivery']&&$f['delivery_fee']===null):?><small>Delivery quote required; contact the supplier. Pickup can be ordered here.</small><?php endif;?><?php endforeach;?><hr><div class="total-row"><span>Merchandise</span><strong><?= money($subtotal) ?></strong></div><p class="small-muted">Delivery and tax are calculated from your selections. Buyer fee: <?= number_format((int)DB::setting('buyer_fee_bps','50')/100,2) ?>% of <?= DB::setting('fee_basis')==='merchandise_plus_delivery'?'merchandise plus delivery, excluding tax':'merchandise, excluding delivery and tax' ?>.</p><button class="btn btn-primary w-100">Review final totals →</button><small>Inventory is reserved for 30 minutes after checkout creation. Current prices are revalidated on the server.</small></form></div><?php endif;?>
